 "content": "def transform(grid):
    g=[row[:] for row in grid]
    bg=max(set(v for row in g for v in row), key=lambda v: sum(r.count(v) for r in g))
    h,w=len(g),len(g[0])
    for color in set(v for row in g for v in row)-{bg}:
        pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
        if len(pts)<2: continue
        # Extend the line defined by the repeated-color pair to both boundaries.
        (r1,c1),(r2,c2)=pts[:2]
        dr=r2-r1; dc=c2-c1
        # Normalize diagonal step
        if dr and dc:
            step=1 if dr>0 else -1
            dc=(1 if dc>0 else -1)
            dr=step
        elif dr:
            dr=1 if dr>0 else -1; dc=0
        elif dc:
            dc=1 if dc>0 else -1; dr=0
        r,c=r1,c1
        while 0<=r-dr<h and 0<=c-dc<w:
            r-=dr; c-=dc
        while 0<=r<h and 0<=c<w:
            if g[r][c]==bg: g[r][c]=color
            r+=dr; c+=dc
    return g

